mapper.select:
select t.team_id, t.team_name, t.description, t.owner_id, t.invite_code, t.status, t.del_flag, t.create_by, t.create_time, t.update_by, t.update_time, t.remark, (select count(*) from ai_team_member tm where tm.team_id = t.team_id) as member_count, (select count(*) from ai_team_project tp where tp.team_id = t.team_id) as project_count from ai_team t
t.del_flag = '0' and t.team_name like concat('%', #{teamName}, '%') and t.status = #{status}
order by t.create_time desc

select tp.access_token
from ai_team_project tp
where tp.team_id = #{teamId} and tp.project_id = #{projectId}

mapper.update:
update ai_team
set invite_code = #{inviteCode}, update_by = #{updateBy}, update_time = #{updateTime}
where team_id = #{teamId}

update ai_team
set team_name = #{teamName}, description = #{description}, update_by = #{updateBy}, update_time = #{updateTime}
where team_id = #{teamId}

update ai_team_member
set role = #{role}, update_by = #{updateBy}, update_time = #{updateTime}
where team_id = #{teamId} and user_id = #{userId}

mapper.select:
select m.msg_id
from ai_team_message m
left join ai_team_message_read r on r.msg_id = m.msg_id and r.user_id = #{userId}
where m.team_id = #{teamId} and m.user_id != #{userId} and r.id is null

    and m.msg_id in
    #{id}

mapper.update:
update ai_team_project_repo
set access_token = #{accessToken}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{repoId}
